"""Append CPU reference to the existing primary-only GPU diagnostic group."""
import json,csv,re
from pathlib import Path
R=Path(__file__).resolve().parents[2];E=R/'output/evaluation';D=E/'diagnostics/cpu_primary_baseline';m=json.loads((D/'manifest.json').read_text());assert m['status']=='completed'
parent=E/'diagnostics'/m['parent_gpu_experiment'];gpu=json.loads((parent/'primary_analysis.json').read_text());cpuinfo=Path('/proc/cpuinfo').read_text();models=re.findall(r'^model name\s*:\s*(.*)',cpuinfo,re.M);m['cpu_model']=models[0] if models else 'unavailable'
rows=[{'backend':'cpu','threads':4,'search_seconds':m['cpu_search_seconds'],'cpu_over_backend_search_ratio':1.0}]
for r in gpu['summary']:rows.append({'backend':r['backend'],'threads':None,'search_seconds':r['search_seconds'],'cpu_over_backend_search_ratio':m['cpu_search_seconds']/r['search_seconds']})
m['search_comparison']=rows;m['candidate_associations_equal_to_gpu']=all(m['associations']==r['candidates'] for r in gpu['summary']);m['generated_peptides_equal_to_gpu']=all(m['generated_peptides']==r['generated_peptides'] for r in gpu['summary']);(D/'manifest.json').write_text(json.dumps(m,indent=2))
with (D/'three_backend_search.csv').open('w') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
lines=['# Marine 全库 + X2 primary-only：CPU baseline 补充','','CPU 4 OpenMP 线程，CPU 型号：'+m['cpu_model']+'。与前一组相同的完整 Marine FASTA、X2 46,862 张谱图、Regular.cfg、单前体规则。一次普通进程，无预热。原始 CPU 匹配/MVH/Peptide 实现和原生批次未改；独立副本只增加主机阶段计时。小样本原生与观察版本最终 PSM SHA256 一致。','','## 完整 MVH 搜索比较','','| 后端 | 搜索秒数 | CPU／后端 |','|---|---:|---:|']
for r in rows:lines.append(f"| {r['backend']} | {r['search_seconds']:.3f} | {r['cpu_over_backend_search_ratio']:.3f}× |")
lines+=['','CPU 与 GPU 的完整 search 均为谱图预处理完成后到搜索返回的 wall 时间，不含 FT2 读取、谱图预处理和导出。CPU 和 GPU 的肽段生成/候选分配实现不同，search 比例包含这些实现差异，不等于纯评分算法或 CPU 单核对 GPU 的比例。','', '## 原生 CPU 批次与计时边界',f"CPU 原生每批 2,000,000 个**已分配肽段**，实际 {m['cpu_scoring_batches']} 批；GPU 每批 12,000,000 个**生成肽段**，39 批。不能将两个 batch 值视为同一参数，也未人为把 CPU batch 改成 12M。",f"CPU 实际生成 {m['generated_peptides']:,} 条肽段，已分配肽段 {m['assigned_peptides']:,}，候选关联 {m['associations']:,}；生成条目与 GPU 一致：{m['generated_peptides_equal_to_gpu']}，候选关联总数与 GPU 一致：{m['candidate_associations_equal_to_gpu']}。",'','| CPU 原生批处理阶段 | 累计秒数 |','|---|---:|',f"| 肽段预处理 | {m['cpu_preprocess_seconds']:.3f} |",f"| 每 scan 评分与结果保留循环 | {m['cpu_scoring_loop_seconds']:.3f} |",f"| 批次对象释放 | {m['cpu_cleanup_seconds']:.3f} |",f"| 原生批处理服务合计 | {m['cpu_batch_service_seconds']:.3f} |",'','CPU 原生批处理合计从已经完成分配的肽段数组进入 processPeptideArrayMvh 起，到预处理、逐 scan 评分/保留和对象释放完成为止；不含 searchDatabaseMvh 的 preMvh/postMvh 等搜索级准备/收尾。GPU 的“完整评分阶段”另有 host packing、设备服务和 host restoration 边界。因此本报告保留 CPU 阶段分解，但不把 CPU scoring loop 直接对齐 GPU fused kernel，也不把 CPU batch 合计当作严格同范围的 GPU 完整评分阶段。三后端主要比较完整 MVH search。','', '## CPU 参考结果比对','','| 相对 CPU | 谱图结果组不同 | Top-1 肽段/电荷一致 | Top-1 分数精确一致 | 公共候选评分差异 |','|---|---:|---:|---:|---:|']
for b,c in m['comparisons_cpu_reference'].items():lines.append(f"| {b} | {c['spectrum_groups_differ']} | {c['top1_peptide_charge_agree']}/{c['spectra_with_results']} | {c['top1_score_exact']}/{c['spectra_with_results']} | {c['common_candidate_scores_differ']} |")
lines+=['','候选/生成数量相同并不替代逐查询等价审计；GPU 已发现的少量保留列表差异仍需定点检查。CPU 只有一遍、无 CPU 亲和性或频率锁定，GPU 数据来自前一时段，不能声称统计显著或推广到所有数据库/线程数。', '本轮只补充 Marine CPU baseline，没有让 CPU 运行 Soil 或规模扩展实验，其余队列仍暂停。所有结果、日志、配置和构建产物在 output。','']
(D/'report.md').write_text('\n'.join(lines))
p=parent/'primary_report.md';s=p.read_text();marker='## CPU baseline 补充';s=s.split(marker)[0].rstrip()+'\n\n'+marker+'\n\n';s+='CPU baseline 已完成，4 线程、相同完整输入和单前体规则；CPU 使用原生 2M assigned-peptide 批次。\n\n| 后端 | 完整 MVH search s | CPU／后端 |\n|---|---:|---:|\n'
for r in rows:s+=f"| {r['backend']} | {r['search_seconds']:.3f} | {r['cpu_over_backend_search_ratio']:.3f}× |\n"
s+='\n详细阶段边界、CPU 参考一致性与原始数据见相邻 cpu_primary_baseline/report.md、manifest.json、batches.csv。CPU 与 GPU 的评分内部边界不同，主要比较完整 MVH search。\n';p.write_text(s)
print(json.dumps({'search_comparison':rows,'cpu_generated':m['generated_peptides'],'cpu_associations':m['associations'],'counts_equal':m['candidate_associations_equal_to_gpu'],'comparisons':m['comparisons_cpu_reference'],'report':str(D/'report.md')},indent=2))
